  const badCursor = cursorError(before as Record<string, unknown>);
  if (badCursor !== undefined) return {valid: false, error: badCursor};
  const {sessionId, updatedAt} = before as {sessionId: string; updatedAt: string | number};
  frame.before = {sessionId, updatedAt};
  return {valid: true, data: frame};
}

